const out = [];
const KEYWORDS = ['price','prize','rate','cost','kitne','kitna','kitni','kimat','keemat','daam','details','detail','info','link','buy','order','size','available','availability','chahiye','chaiye','dm','how much','amount','cod','book','booking'];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  const entries = body.entry || [];
  for (const entry of entries) {
    for (const ch of (entry.changes || [])) {
      const v = ch.value || {};
      let rec = null;
      if (body.object === 'instagram' && ch.field === 'comments') {
        if (v.parent_id) continue;
        rec = { platform: 'instagram', accountId: entry.id, commentId: v.id, postId: v.media && v.media.id, mediaType: (v.media && v.media.media_product_type) || 'FEED', commentText: v.text || '', fromId: v.from && v.from.id, fromName: v.from && (v.from.username || v.from.name) };
      } else if (body.object === 'page' && ch.field === 'feed') {
        if (v.item !== 'comment' || v.verb !== 'add') continue;
        if (v.parent_id && v.parent_id !== v.post_id) continue;
        rec = { platform: 'facebook', accountId: entry.id, commentId: v.comment_id, postId: v.post_id, mediaType: 'POST', commentText: v.message || '', fromId: v.from && v.from.id, fromName: v.from && v.from.name };
      }
      if (!rec || !rec.commentId || !rec.fromId) continue;
      if (String(rec.fromId) === String(entry.id)) continue;
      const lower = String(rec.commentText).toLowerCase();
      const words = lower.split(/[^a-z0-9]+/);
      const hit = KEYWORDS.find(k => k.indexOf(' ') > -1 ? lower.includes(k) : words.includes(k));
      out.push({ json: Object.assign({}, rec, { buyingIntent: !!hit, matchedKeyword: hit || null }) });
    }
  }
}
return out;

