  '17900001000000002': ['bomkai-silk-kurta-gold', 'kotpad-organic-kurta-earth'],
  '10000000001_20000000002': ['pasapalli-nehru-jacket-black']
};
const FALLBACK = ['sambalpuri-ikat-kurta-maroon', 'bomkai-silk-kurta-gold', 'kotpad-organic-kurta-earth'];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const mapped = POST_MAP[String(j.postId)];
  const handles = mapped && mapped.length ? mapped : FALLBACK;
  handles.slice(0, 10).forEach((h, idx) => {
    out.push({ json: Object.assign({}, j, { handle: h, handleIndex: idx, mappedBy: mapped ? 'post_map' : 'fallback_bestsellers' }) });
  });
}
return out;

