const NL = String.fromCharCode(10);
const ctxItems = $('Resolve Products for Post').all();
const prods = $input.all();
const groups = {};
const rupees = (paise) => '₹' + (Number(paise) / 100).toLocaleString('en-IN');
prods.forEach((it, i) => {
  const ctx = (ctxItems[i] && ctxItems[i].json) || {};
  const p = it.json || {};
  if (!p.title || !ctx.commentId) return;
  const productUrl = 'https://' + ctx.shopDomain + '/products/' + p.handle + '?utm_source=' + ctx.platform + '&utm_medium=comment_dm&utm_campaign=comment_to_dm';
  const variants = Array.isArray(p.variants) ? p.variants : [];
  const sizes = variants.filter(v => v.available).map(v => v.option1).filter(Boolean);
  const inStock = p.available !== false && (variants.length === 0 || sizes.length > 0);
  const mrp = Number(p.compare_at_price) > Number(p.price) ? ' (MRP ' + rupees(p.compare_at_price) + ')' : '';
  const subtitle = (rupees(p.price) + mrp + ' • ' + (inStock ? 'Sizes: ' + sizes.join('/') : 'Sold out')).slice(0, 80);
  let img = p.featured_image || (p.images && p.images[0]) || '';
  if (String(img).indexOf('//') === 0) img = 'https:' + img;
  const el = {
    title: String(p.title).slice(0, 80),
    subtitle: subtitle,
    image_url: img,
    default_action: { type: 'web_url', url: productUrl },
    buttons: [
      { type: 'web_url', url: productUrl, title: inStock ? 'Buy Now' : 'View Product' },
      { type: 'web_url', url: 'https://wa.me/' + ctx.waNumber + '?text=' + encodeURIComponent('ORDER ' + p.handle), title: 'Order on WhatsApp' }
    ]
  };
  if (!groups[ctx.commentId]) groups[ctx.commentId] = { ctx: ctx, elements: [], lines: [] };
  groups[ctx.commentId].elements.push(el);
  groups[ctx.commentId].lines.push('• ' + p.title + ' - ' + rupees(p.price) + NL + productUrl);
});
return Object.keys(groups).map(cid => {
  const g = groups[cid];
  const c = g.ctx;
  const carouselBody = { recipient: { comment_id: c.commentId }, message: { attachment: { type: 'template', payload: { template_type: 'generic', elements: g.elements.slice(0, 10) } } } };
  const fallbackBody = { recipient: { comment_id: c.commentId }, message: { text: 'Hi ' + (c.fromName || '') + '! 👋 Aapne ' + c.brandName + ' ki post pe poocha tha. Yeh rahe details:' + NL + NL + g.lines.join(NL + NL) } };
  return { json: {
    platform: c.platform,
    accountId: c.accountId,
    commentId: c.commentId,
    fromName: c.fromName,
    postId: c.postId,
    matchedKeyword: c.matchedKeyword,
    productCount: g.elements.length,
    carouselBody: carouselBody,
    fallbackBody: fallbackBody,
    publicReplyText: 'Hi ' + (c.fromName || '') + '! Details aapke DM mein bhej diye hain 📩 (Message requests bhi check kar lijiye)'
  } };
});

const out = [];
const TRACK = ['track','status','kahan','kaha','where','delivery','deliver','shipment','parcel','courier','dispatch','aayega','pahunch','pohch'];
const SUPPORT = ['cancel','return','refund','exchange','wapas','replace','complaint','damage','wrong'];
for (const item of $input.all()) {
  const j = item.json;
  const m = j.messages && j.messages[0];
  if (!m) continue;
  let text = '';
  if (m.type === 'text') text = (m.text && m.text.body) || '';
  else if (m.type === 'button') text = (m.button && (m.button.text || m.button.payload)) || '';
  else if (m.type === 'interactive' && m.interactive) {
    const r = m.interactive.button_reply || m.interactive.list_reply || {};
    text = r.id || r.title || '';
  }
  const raw = String(text).trim();
  const lower = raw.toLowerCase();
  const idMatch = raw.match(/ord[- ]?#?([0-9]{4,})/i) || raw.match(/#([0-9]{4,})/);
  const orderId = idMatch ? 'ORD-' + idMatch[1] : null;
  const orderCmd = raw.match(/^order[ ]+([a-z0-9-]+)$/i);
  let intent = 'menu';
  let handle = null;
  if (orderCmd && !idMatch) { intent = 'new_order'; handle = orderCmd[1].toLowerCase(); }
  else if (SUPPORT.some(w => lower.includes(w))) intent = 'support';
  else if (orderId || TRACK.some(w => lower.includes(w))) intent = 'track';
  else if (lower.includes('my order') || lower.includes('orders') || lower.includes('history')) intent = 'my_orders';
  const name = (j.contacts && j.contacts[0] && j.contacts[0].profile && j.contacts[0].profile.name) || 'there';
  out.push({ json: { phone: m.from, name: name, text: raw, intent: intent, orderId: orderId, handle: handle, msgId: m.id } });
}
return out;

