const NL = String.fromCharCode(10);
const LABEL = { processing: '📦 Packing in progress', shipped: '🚚 Shipped', out_for_delivery: '🛵 Out for Delivery', delivered: '✅ Delivered' };
return $input.all().map(item => {
  const c = item.json;
  const orders = c.orders || [];
  const o = c.orderId ? orders.find(x => x.id === c.orderId) : orders[0];
  let reply;
  if (!o) {
    reply = 'Hi ' + c.name + '! 🙏 ' + (c.orderId ? c.orderId + ' is number pe nahi mila.' : 'Is number pe koi order nahi mila.') + NL + 'Order number check karke dobara bhejiye (e.g. ORD-10452) ya *MENU* likhiye.';
  } else {
    const items = o.items.map(i => '• ' + i.title + ' (' + i.size + ') x' + i.qty).join(NL);
    const tl = o.timeline.map(t => (t.done ? '✅ ' : '⏳ ') + t.label + ' - ' + t.at).join(NL);
    const lines = [
      '📦 *Order ' + o.id + '*',
      'Status: ' + (LABEL[o.status] || o.status),
      '',
      items,
      'Total: ₹' + o.total.toLocaleString('en-IN') + ' (' + o.payment + ')'
    ];
    if (o.courier) lines.push('Courier: ' + o.courier + ' | AWB: ' + o.awb);
    lines.push('ETA: ' + o.eta);
    if (o.trackingUrl) lines.push('🔗 Live tracking: ' + o.trackingUrl);
    lines.push('', '*Timeline*', tl, '', 'Cancel / return ke liye *CANCEL ' + o.id + '* likhiye. Menu ke liye *MENU*.');
    reply = lines.join(NL);
  }
  return { json: { phone: c.phone, reply: reply } };
});

const NL = String.fromCharCode(10);
const LABEL = { processing: '📦 Packing', shipped: '🚚 Shipped', out_for_delivery: '🛵 Out for delivery', delivered: '✅ Delivered' };
return $input.all().map(item => {
  const c = item.json;
  const orders = (c.orders || []).slice(0, 5);
  let reply;
  if (!orders.length) {
    reply = 'Hi ' + c.name + '! Is number pe abhi tak koi order nahi hai. Instagram pe kisi post pe *price* comment karke product dekh sakte hain 🛍️';
  } else {
    const rows = orders.map(o => '*' + o.id + '* - ' + o.placedOn + NL + (LABEL[o.status] || o.status) + ' | ₹' + o.total.toLocaleString('en-IN'));
    reply = 'Hi ' + c.name + '! Aapke recent orders:' + NL + NL + rows.join(NL + NL) + NL + NL + 'Kisi order ko track karne ke liye order number bhejiye (e.g. *ORD-10452*).';
  }
  return { json: { phone: c.phone, reply: reply } };
});

const NL = String.fromCharCode(10);
const CATALOG = {
