    reply = 'Hi ' + c.name + '! Yeh product abhi catalog mein nahi mila. Please post pe dobara *price* comment karein ya *MENU* likhiye.';
  } else {
    const draft = 'DRAFT-' + String(Date.now()).slice(-6);
