const MAP = { confirmed: 'order_confirmed_v1', shipped: 'order_shipped_v1', out_for_delivery: 'order_out_for_delivery_v1', delivered: 'order_delivered_v1' };
const out = [];
for (const item of $input.all()) {
  const b = item.json.body || item.json;
  const tpl = MAP[b.status];
  if (!tpl || !b.phone) continue;
  let detail = '';
  if (b.status === 'confirmed') detail = b.itemTitle || 'your order';
  else if (b.status === 'shipped') detail = (b.courier || 'Courier') + ' | AWB ' + (b.awb || '-') + ' | ' + (b.trackingUrl || '');
  else if (b.status === 'out_for_delivery') detail = 'ETA: ' + (b.eta || 'today');
  else detail = 'Delivered ' + (b.deliveredAt || 'today');
  out.push({ json: {
    phone: String(b.phone).replace(/[^0-9]/g, ''),
    templateRef: tpl + '|en',
    p1: b.customerName || 'Customer',
    p2: b.orderId || '-',
    p3: detail
  } });
}
return out;
